import { readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, test } from "vitest";

// The package index is generated by the build, which runs again on publish. A module that is public API but not a
// component (clinical-format) must come from the generator, not a hand edit the next build would drop (tasks.md P28-T1). Tests run from the package directory.
const index = readFileSync(join(process.cwd(), "index.ts"), "utf8");

describe("index", () => {
    test("exports the clinical-format functions", () => {
        expect(index).toContain(
            'export { ageParts, formatQuantity, toIsoDuration } from "./components/clinical-format";',
        );
    });

    test("exports a record list and a healthcare view", () => {
        expect(index).toMatch(/\bRecordList\b/);
        expect(index).toMatch(/\bObservationView\b/);
    });
});
